(function(){'use strict';const panel=document.createElement('details');panel.id='dicePanel';panel.className='story-settings';panel.innerHTML='<summary>โต๊ะทอยเต๋า / กรอกผลเต๋าจริง</summary><p>เครื่องมือทอยอิสระ ผลยังไม่แทนการคำนวณโจมตีของเกมอัตโนมัติ</p><label>จำนวนลูก<input id="diceCount" type="number" min="1" max="20" value="1"></label><label>ชนิดเต๋า<select id="diceSides"><option>20</option><option>4</option><option>6</option><option>8</option><option>10</option><option>12</option><option>100</option></select></label><label>โบนัส<input id="diceBonus" type="number" value="0" min="-1000" max="1000"></label><label>วิธีคิด<select id="diceMode"><option value="normal">รวมปกติ</option><option value="advantage">ได้เปรียบ: สูงสุดจาก 2D20</option><option value="disadvantage">เสียเปรียบ: ต่ำสุดจาก 2D20</option></select></label><p id="diceInstruction"></p><div id="diceTable" aria-label="โต๊ะเต๋ามองจากด้านบน"><span id="diceFace">D20</span></div><button id="diceThrow">คลิกปล่อยเต๋า</button><label>ทอยเอง: กรอกแต้มแต่ละลูก คั่นด้วยจุลภาค<input id="diceValues" placeholder="เช่น 4, 6"></label><button id="diceManual">ยืนยันแต้มที่ทอยเอง</button><p id="diceResult" role="status"></p>';
document.getElementById('storySettings').before(panel);const $=id=>document.getElementById(id);let busy=false;
const rule=()=>DecideDice.spec(Number($('diceCount').value),Number($('diceSides').value),Number($('diceBonus').value));
function instruction(){try{const r=rule();$('diceInstruction').textContent='ใช้ '+r.count+'D'+r.sides+' • กรอกแต้มหน้าลูกเต๋า 1–'+r.sides+' จำนวน '+r.count+' ค่า เกมบวกโบนัส '+r.bonus+' ให้เอง';}catch(e){$('diceInstruction').textContent=e.message;}}
for(const id of ['diceCount','diceSides','diceBonus','diceMode'])$(id).onchange=()=>{if($('diceMode').value!=='normal'){$('diceCount').value=2;$('diceSides').value=20;}instruction();};
function show(r,source){$('diceFace').textContent=r.values.join(' · ');$('diceResult').textContent=source+': '+r.values.join(', ')+' → '+r.subtotal+' + ('+r.bonus+') = '+r.total;}
$('diceThrow').onclick=async()=>{if(busy)return;try{const r=DecideDice.roll(rule(),$('diceMode').value);busy=true;$('diceThrow').disabled=$('diceManual').disabled=true;$('diceFace').classList.add('rolling');await new Promise(resolve=>setTimeout(resolve,900));show(r,'ทอยในเกม');}catch(e){$('diceResult').textContent=e.message;}finally{busy=false;$('diceThrow').disabled=$('diceManual').disabled=false;$('diceFace').classList.remove('rolling');}};
$('diceManual').onclick=()=>{if(busy)return;try{const raw=$('diceValues').value.trim();if(!/^\d+(\s*,\s*\d+)*$/.test(raw))throw Error('กรอกจำนวนเต็มแต่ละลูกคั่นด้วยจุลภาค');show(DecideDice.resolve(rule(),raw.split(',').map(Number),$('diceMode').value),'กรอกเอง');}catch(e){$('diceResult').textContent=e.message;}};instruction();
})();
